/* HEXA BATTLEGROUNDS upgrade — PART 10 OF 38. Only for databases that already ran setup part-01…; Run in order. Safe to re-run. */ create or replace function _tick(p_arena uuid, p_force boolean default false) returns boolean language plpgsql as $$ declare a arenas; r record; tm teams; c float8[]; xy float8[]; v_tick int; v_bucket bigint; v_changed boolean := false; v_sched text[]; v_next int; v_at timestamptz; v_target int; begin if not pg_try_advisory_xact_lock(hashtext('tick' || p_arena::text)) then return false; end if; select * into a from arenas where id = p_arena; if a.id is null or a.paused then return false; end if; if not p_force and a.last_tick_at is not null and a.last_tick_at > now() - interval '800 milliseconds' then return false; end if; update arenas set last_tick_at = now() where id = p_arena; if a.phase = 'shuttle' and now() >= a.shuttle_arrive_at then update arenas set phase = 'roles', roles_deadline = now() + _secs(_cfg(a.event_id, 'roles_seconds')) where id = p_arena; update teams set location_id = 'gate_1', state = 'idle' where arena_id = p_arena and ready; perform _feed(p_arena, 'shuttle.arrived', '{}'::jsonb); v_changed := true; end if; select * into a from arenas where id = p_arena; if a.phase = 'roles' and now() >= a.roles_deadline then perform _finalize_roles(p_arena); update arenas set phase = 'play', play_started_at = now() where id = p_arena; perform _feed(p_arena, 'role.assignment.completed', '{}'::jsonb); perform _feed(p_arena, 'map.revealed', '{}'::jsonb); perform _set_match_phase(p_arena, 0); v_changed := true; end if; select * into a from arenas where id = p_arena; if a.phase not in ('play', 'finale') then if v_changed then perform _ping_arena(p_arena, 'phase'); end if; return v_changed; end if; for r in select id from teams where arena_id = p_arena and state = 'traveling' and travel_arrive_at <= now() loop perform _arrive(r.id); v_changed := true; end loop; for r in select id from battles where arena_id = p_arena and status = 'active' and deadline <= now() loop perform _resolve_battle(r.id, null); v_changed := true; end loop; for r in select id, kind, sync_round_id from mission_instances where arena_id = p_arena and status = 'active' and deadline <= now() and kind <> 'battle' loop perform _fail(r.id, 'expired'); v_changed := true; end loop; for r in select id from teams where arena_id = p_arena and state = 'recovery' and recovery_deadline <= now() loop perform _respawn(r.id, 'timeout'); v_changed := true; end loop; for r in select id from sync_rounds where arena_id = p_arena and status = 'active' and deadline <= now() loop update sync_rounds set status = 'closed' where id = r.id; update arenas set sync_round_id = null where id = p_arena and sync_round_id = r.id; perform _feed(p_arena, 'sync.closed', '{}'::jsonb); v_changed := true; end loop; select * into a from arenas where id = p_arena; if a.phase = 'play' and a.match_phase < 4 and a.phase_next_at is not null and now() >= a.phase_next_at then perform _set_match_phase(p_arena, a.match_phase + 1); v_changed := true; end if; select * into a from arenas where id = p_arena; if a.phase = 'play' and not a.zone_hold and a.zone_next_at is null and a.zone_stage < 5 then v_target := _phase_zone_target(a.match_phase); if a.zone_stage < v_target then update arenas set zone_next_at = now() + _secs(_cfg(a.event_id, 'zone_warning')) where id = p_arena; perform _feed(p_arena, 'zone.warning', jsonb_build_object('stage', a.zone_stage + 1)); v_changed := true; end if; end if; select * into a from arenas where id = p_arena; if a.phase = 'play' and _cfg(a.event_id, 'zone_auto') = 1 and a.zone_next_at is null and a.zone_stage < 5 and not a.zone_hold then v_sched := string_to_array(_cfg_text(a.event_id, 'zone_schedule'), ','); v_next := trim(v_sched[a.zone_stage + 1])::int; if v_next is not null then v_at := a.play_started_at + make_interval(mins => v_next); if now() >= v_at - _secs(_cfg(a.event_id, 'zone_warning')) then update arenas set zone_next_at = greatest(v_at, now() + interval '10 seconds') where id = p_arena; perform _feed(p_arena, 'zone.warning', jsonb_build_object('stage', a.zone_stage + 1)); v_changed := true; end if; end if; end if; select * into a from arenas where id = p_arena; if a.zone_next_at is not null and now() >= a.zone_next_at then perform _zone_advance(p_arena); v_changed := true; end if; select * into a from arenas where id = p_arena; if a.phase = 'play' then c := _zone_circle(a.event_id, a.zone_stage); v_tick := greatest(2, _cfg(a.event_id, 'zone_tick_seconds')); v_bucket := floor(extract(epoch from now()) / v_tick)::bigint; for tm in select * from teams where arena_id = p_arena and ready and state <> 'recovery' and (zone_hit_at is null or zone_hit_at <= now() - _secs(v_tick)) loop xy := _team_xy(tm); if not _in_circle(c, xy[1], xy[2]) then update teams set zone_hit_at = now() where id = tm.id; perform _damage(tm.id, _cfg(a.event_id, 'zone_tick_damage'), 'zone_damage', 'zt-' || v_bucket, 'Outside the safe zone'); perform _ping_team(tm.id, 'zone'); v_changed := true; end if; end loop; end if; select * into a from arenas where id = p_arena; if a.red_at is not null and now() >= a.red_at then perform _red_strike(p_arena); v_changed := true; elsif a.phase = 'play' and a.red_at is null and a.match_phase >= 2 and _cfg(a.event_id, 'red_interval') > 0 and coalesce(a.last_red_at, a.phase_started_at, a.play_started_at) < now() - make_interval(mins => _cfg(a.event_id, 'red_interval')) then perform _red_spawn(p_arena); v_changed := true; end if; if a.phase = 'play' and _cfg(a.event_id, 'airdrop_interval') > 0 and coalesce(a.last_airdrop_at, a.play_started_at) < now() - make_interval(mins => _cfg(a.event_id, 'airdrop_interval')) then perform _spawn_airdrop(p_arena, null, (array['common', 'common', 'rare', 'mystery', 'intel', 'cursed', 'legendary'])[1 + floor(random() * 7)::int]); v_changed := true; end if; update airdrops set status = 'expired' where arena_id = p_arena and status = 'open' and expires_at <= now(); if found then v_changed := true; end if; update mission_instances mi set status = 'cancelled' from airdrops ad where mi.airdrop_id = ad.id and ad.status = 'expired' and mi.status = 'active'; update alliances set status = 'expired' where arena_id = p_arena and status = 'proposed' and created_at < now() - interval '2 minutes'; update alliances set status = 'ended' where arena_id = p_arena and status = 'active' and expires_at <= now(); if v_changed then perform _zone_publish(p_arena); perform _ping_arena(p_arena, 'tick'); end if; return v_changed; end $$;
